-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS picking_batches_update_audit ON inventory.picking_batches;
CREATE TRIGGER picking_batches_update_audit BEFORE UPDATE ON inventory.picking_batches
